{"code": "import zipfile, re, os

OUTPUT = '/root/inventory_report_ready.hwpx'

# Check it's a valid ZIP
try:
    with zipfile.ZipFile(OUTPUT, 'r') as z:
        print('Valid ZIP file.')
        print('Contents:')
        for info in z.infolist():
            print(f'  {info.filename:50s} compress={info.compress_type} size={info.file_size}')

        # Check for remaining placeholders
        has_placeholders = False
        for info in z.infolist():
            with z.open(info.filename) as f:
                try:
                    content = f.read().decode('utf-8')
                    matches = re.findall(r'\{\{[^}]+\}\}', content)
                    if matches:
                        print(f'WARNING: placeholders in {info.filename}: {matches}')
                        has_placeholders = True
                except:
                    pass

        if not has_placeholders:
            print('No remaining placeholders.')

        # Check linesegarray in section0.xml
        with z.open('Contents/section0.xml') as f:
            content = f.read().decode('utf-8')
            if 'linesegarray' in content.lower():
                print('WARNING: linesegarray still present!')
                # Show lines with it
                for line in content.split('\n'):
                    if 'linesegarray' in line.lower():
                        print('  Line:', line[:200])
            else:
                print('No linesegarray elements found.')

            # Show a sample of replaced text
            print('\n--- Sample content ---')
            for line in content.split('><'):
                if 'hp:t' in line:
                    print(line)

except Exception as e:
    print(f'Error: {e}')
